 return nil
}

func (r *Reporter) save() error {
 data, err := json.MarshalIndent(r.state, "", "  ")
 if err != nil { return fmt.Errorf("encoding telemetry state: %w", err) }
 dir := filepath.Dir(r.path)
 f, err := os.CreateTemp(dir, ".telemetry-*")
 if err != nil { return fmt.Errorf("creating telemetry state: %w", err) }
 defer os.Remove(f.Name())
 if err := f.Chmod(0600); err != nil { f.Close(); return err }
 if _, err := f.Write(data); err != nil { f.Close(); return fmt.Errorf("writing telemetry state: %w", err) }
 if err := f.Close(); err != nil { return fmt.Errorf("closing telemetry state: %w", err) }
 if err := os.Rename(f.Name(), r.path); err != nil { return fmt.Errorf("saving telemetry state: %w", err) }
 return nil
}
EOF
